function numWays() {
  const memo = new Map();

  function numWaysRec(i) {
    if (i > 21) {
      return 1;
    }
    if (i >= 16 && i <= 21) {
      return 0;
    }
    if (memo.has(i)) {
      return memo.get(i);
    }
    let res = 0;
    for (let card = 1; card <= 10; card++) {
      res += numWaysRec(i + card);
    }
