class NumWays {
  private Map<Integer, Integer> memo = new HashMap<>();

  private int numWaysRec(int i) {
    if (i > 21) {
      return 1;
    }
    if (i >= 16 && i <= 21) {
      return 0;
    }
    if (memo.containsKey(i)) {
      return memo.get(i);
    }
    int res = 0;
    for (int card = 1; card <= 10; card++) {
      res += numWaysRec(i + card);
    }
    memo.put(i, res);
    return res;
  }

  public int solve() {
    return numWaysRec(0);
  }
}

